# Generated by build.py from recipe.yml for recipe http-download-many-files-in-parallel. Do not edit.
Set-Location $PSScriptRoot
cmd /c 'sh make-site.sh'
$server0 = Start-Process surl -ArgumentList '--max-connections-per-address', '8', '--directory', 'site', 'http://127.0.0.1:8080/' -PassThru -NoNewWindow
Start-Sleep 1
try { curl.exe -s -f --parallel --parallel-max 8 --create-dirs -o "out/f#1.bin" -w "%{http_code} %{size_download}\n" "http://127.0.0.1:8080/f[1-50].bin" } finally { Stop-Process $server0 }
